const GENERAL_SPREAD = {
  id: "general",
  en: ["The energy around my situation", "What I need to know", "Advice for the situation"] as [string, string, string],
  th: ["\u0e1e\u0e25\u0e31\u0e07\u0e23\u0e2d\u0e1a\u0e15\u0e31\u0e27\u0e09\u0e31\u0e19", "\u0e2a\u0e34\u0e48\u0e07\u0e17\u0e35\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e23\u0e39\u0e49", "\u0e04\u0e33\u0e41\u0e19\u0e30\u0e19\u0e33"] as [string, string, string],
};

/** Three position labels chosen from the question + topic only — never
 *  from the cards. Deterministic: same inputs, same spread. */
export function pickSpread(question: string, topic: Topic, lang: "th" | "en"): [string, string, string] {
  const q = question.toLowerCase();
  for (const s of SPREADS) {
    if (s.id === "love" && topic !== "love" && !s.test.test(question)) continue;
    // A career/money question that names a partner ("my husband's
    // salary") is about work, not the relationship: never route it
    // to the love spread.
    if (s.id === "love" && (topic === "career" || topic === "money")) continue;
    if (s.id === "work" && (topic === "career" || topic === "money")) return lang === "th" ? s.th : s.en;
    if (s.test.test(q) || s.test.test(question)) return lang === "th" ? s.th : s.en;
  }
  if (topic === "love") {
    const s = SPREADS.find((x) => x.id === "love")!;
    return lang === "th" ? s.th : s.en;
  }
  if (topic === "career" || topic === "money") {
    const s = SPREADS.find((x) => x.id === "work")!;
    return lang === "th" ? s.th : s.en;
  }
  return lang === "th" ? GENERAL_SPREAD.th : GENERAL_SPREAD.en;
}

// --- Prompt builder (server builds from D1, never from the client) ---

export type PromptCard = {
  name: string;
  reversed: boolean;
  keywords: string[];
  meaning: string;
  topicNote: string | null;
  imagery: string | null;
};

export type PrevReading = {
  topic: string;
  cardNames: string[];
  summary: string;
};

export function toPromptCard(card: CardView, reversed: boolean, topic: Topic): PromptCard {
  const topicNote =
    topic === "love" ? card.love :
    topic === "career" ? card.career :
    topic === "money" ? card.money :
    topic === "health" ? card.health : null;
  return {
    // Card names are always written in English (normal for Thai readers).
    name: card.nameEn ?? card.name,
    reversed,
    keywords: reversed ? card.keywordsReversed : card.keywordsUpright,
    meaning: reversed ? card.reversed : card.upright,
    topicNote,
    imagery: card.imagery ?? null,
  };
}

